// #add75b לאחר אישור האימייל — без экрана «הקמת חשבון חברה» (/setup): у зарегистрированного 14.11 аккаунта
// SIGNUP14 (компания «QA add75b בע"מ», мастер на шаге 1) прямой заход на /setup уводит в мастер / на главную,
// вторая компания не создаётся. НОВЫХ РЕГИСТРАЦИЙ НЕТ: только существующая сессия .qa/auth/signup14.json.
// Кейсы: .qa/tests/signup/SU-06, SU-07 (SU-M2 — свежая регистрация и повтор ссылки, только вручную). План: specs/signup.md.
// Аккаунт мастер НЕ продвигает: тест ничего не нажимает. Нет файла сессии — тесты пропускаются.
import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import { authState } from '../helpers/tenderflow';
import { sbSelect, sbSessionHere } from '../helpers/supabase';

const SIGNUP14 = authState('signup14');
const COMPANY = 'QA add75b בע"מ';

test.skip(!fs.existsSync(SIGNUP14), 'Нет сессии signup14 (.qa/auth/signup14.json) — npm run qa-login:manual -- signup14');
test.use({ storageState: SIGNUP14 });

test.describe('אחרי אישור האימייל — חשבון חדש עם חברה', () => {
  test('/setup מעביר לאשף או לדף הבית, בלי "הקמת חשבון חברה", והמשתמש חבר בחברה אחת בלבד #add75b @desktop', async ({ page }) => {
    // SU-06: מה רצוי — «בלי מסך ביניים»; программист: /setup только для пользователя без компании.
    await page.goto('/setup');
    await page.waitForURL((u) => u.pathname === '/onboarding' || u.pathname === '/');
    await expect(page.getByText('הקמת חשבון חברה')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'יצירת חברה' })).toHaveCount(0);

    const s = await sbSessionHere(page);
    const memberships = await sbSelect<{ company_id: string }>(s, `company_members?select=company_id&user_id=eq.${s.userId}`);
    expect(memberships, 'после /setup пользователь состоит ровно в одной компании').toHaveLength(1);
  });

  test('/onboarding שלב 1: "שם החברה" מולא מההרשמה ("QA add75b בע"מ") #add75b @desktop', async ({ page }) => {
    // SU-07: компания создана по имени из регистрации, имя повторно не спрашивают.
    await page.goto('/onboarding');
    await expect(page.getByRole('navigation', { name: 'שלבי האשף' }).getByText('שלב 1 מתוך 4', { exact: true })).toBeVisible();
    await expect(page.getByRole('textbox', { name: /שם החברה/ })).toHaveValue(COMPANY);
  });
});
